package com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.spec.skill;import com.shatteredpixel.shatteredpixeldungeon.rules.contract.v6.identity.StableId;public final class TemporaryHpEffectSpec implements EffectSpec{public enum TemporaryHpStackingPolicy{MAX,ADD,REPLACE}private final StableId effectId;private final ValueSpec amount;private final DurationSpec duration;private final TemporaryHpStackingPolicy stacking;public TemporaryHpEffectSpec(StableId id,ValueSpec amount,DurationSpec duration,TemporaryHpStackingPolicy stacking){if(id==null||amount==null||duration==null||stacking==null)throw new IllegalArgumentException("temporary HP fields required");effectId=id;this.amount=amount;this.duration=duration;this.stacking=stacking;}@Override public StableId effectId(){return effectId;}@Override public EffectFamily family(){return EffectFamily.RECOVERY_DEFENSE;}@Override public EffectVariantKey variantKey(){return EffectVariantKey.TEMPORARY_HP;}public ValueSpec amount(){return amount;}public DurationSpec duration(){return duration;}public TemporaryHpStackingPolicy stacking(){return stacking;}}
